void UpgradeCenter::linkUpgrade(UpgradeTemplate *node)
{
    if(!node) return;
    node->m_prev=0;
    node->m_next=m_upgradeList;
    if(m_upgradeList) m_upgradeList->m_prev=node;
    m_upgradeList=node;
}

