void UpgradeCenter::unlinkUpgrade(UpgradeTemplate *node)
{
    if(!node) return;
    if(node->m_next) node->m_next->m_prev=node->m_prev;
    if(node->m_prev) node->m_prev->m_next=node->m_next;
    else m_upgradeList=node->m_next;
}

