// FUNCTION: BFME2 0x0026F8D6 size=102 name=?friend_resolveSubUpgradeNames@UpgradeTemplate@@QAEXXZ evidence=N:ledger
void UpgradeTemplate::friend_resolveSubUpgradeNames()
{
	if (m_subUpgradeTemplateNames.empty())
		return;
	UnsignedInt count = m_subUpgradeTemplateNames.size();
	std::vector<const UpgradeTemplate *> &subUpgrades = m_subUpgradeTemplates;
	subUpgrades.reserve(count);
	for (UnsignedInt i = 0; i < count; ++i)
	{
		const UpgradeTemplate *subUpgrade = TheUpgradeCenter->findUpgrade(m_subUpgradeTemplateNames[i]);
		if (subUpgrade)
			subUpgrades.push_back(subUpgrade);
	}
	m_subUpgradeTemplateNames.clear();
}

