void UpgradeCenter::rva0026F93C()
{
    for (UpgradeTemplate *upgrade=m_upgradeList;upgrade;upgrade=upgrade->m_next)
        upgrade->friend_resolveSubUpgradeNames();
}

// FUNCTION: BFME2 0x0026F952 size=179 name=?newUpgrade@UpgradeCenter@@QAEPAVUpgradeTemplate@@ABVAsciiString@@_N@Z evidence=N:ledger
UpgradeTemplate *UpgradeCenter::newUpgrade(const AsciiString &name,bool assignMaskBit)
{
    UpgradeTemplate *upgrade=new UpgradeTemplate;
    const UpgradeTemplate *defaults=findUpgrade("DefaultUpgrade");
    if (defaults) *upgrade=*defaults;
    upgrade->setUpgradeName(name);
    upgrade->setUpgradeNameKey(TheNameKeyGenerator->nameToKey(name));
    if (assignMaskBit) {
        upgrade->m_maskIndex=m_nextTemplateMaskBit;
        ++m_nextTemplateMaskBit;
    }
    linkUpgrade(upgrade);
    return upgrade;
}

